'use strict';

/**
 * Vehicle — the core entity managed through the fulfillment pipeline.
 *
 * @typedef {Object} Vehicle
 * @property {string}            id           - Unique hex ID (generated by db.js)
 * @property {string|null}       vin          - 17-char VIN. Always null in sale_processing,
 *                                              optional in fulfillment, required in fulfilled.
 * @property {string}            make         - e.g. "Toyota"
 * @property {string}            model        - e.g. "Camry"
 * @property {number}            year         - Model year, e.g. 2023
 * @property {string}            color        - e.g. "White"
 * @property {Stage}             stage        - Current pipeline stage (see Stage below)
 * @property {number}            price        - Sale price in USD
 * @property {number}            mileage      - Odometer reading in miles
 * @property {StageHistoryEntry[]} stageHistory - Ordered list of stage transitions for this vehicle
 * @property {Date}              createdAt    - When the vehicle entered the system
 * @property {Date}              updatedAt    - Last modification time
 */

/**
 * Stage — the three pipeline stages a vehicle moves through, in order.
 *
 * @typedef {'sale_processing' | 'fulfillment' | 'fulfilled'} Stage
 *
 * Valid transitions (enforced in server/src/utils/transitions.js):
 *   sale_processing → fulfillment
 *   fulfillment     → fulfilled   (requires a valid VIN)
 */

/**
 * StageHistoryEntry — one entry in Vehicle.stageHistory.
 * Embedded directly on the vehicle document.
 *
 * @typedef {Object} StageHistoryEntry
 * @property {Stage}       stage         - The stage that was entered
 * @property {Stage|null}  previousStage - The stage before this one, or null for the first entry
 * @property {Date}        timestamp     - When the transition occurred
 */

/**
 * StageLog — same transition event written to a separate flat collection
 * as an audit trail. Queryable by vehicleId via db.stageLogs.findByVehicleId().
 *
 * @typedef {Object} StageLog
 * @property {string}      id            - Unique hex ID
 * @property {string}      vehicleId     - References Vehicle.id
 * @property {Stage}       stage         - The stage that was entered
 * @property {Stage|null}  previousStage - The stage before this one, or null for the first entry
 * @property {Date}        timestamp     - When the transition occurred
 */

module.exports = {};
